// The DEADBALL photo & illustration archive: public-domain (and a few CC0 / CC-BY) press photos,
// engravings, natural-history plates, ads and cartoons, tagged so the newsroom, the crime desk
// and the client can pick a picture for a story, an incident, a world event, a mail item, an
// event card, a BBS post or a "Moment" card.
//
// Items are generated by tools/assets/archive/build.py into ./archive-data.ts. Images live on the
// client at images/archive/<id>-<w>.png for w in ARCHIVE_SIZES (1-bit, dithered):
//   400 (400×240 full-screen cutaway; only items with `full`), 160 (160×100 story lead),
//   96 (96×72 event card / mail), 48 (48×36 thumb).
// Everything here is pure and deterministic (no Rng needed: choices hash the seed string).

import { ARCHIVE_DATA } from "./archive-data.ts";
import type { IncidentKind } from "./incidents.ts";

export interface ArchiveItem {
  /** "raccoon-03": images/archive/raccoon-03-<w>.png */
  id: string;
  tags: string[];
  /** Short neutral caption ("A raccoon, as drawn by a naturalist, 1890s"). */
  caption: string;
  /** Credit line ("Library of Congress, Bain News Service"; author for CC-BY). */
  credit: string;
  /** Source page URL (LoC item page when known, else the Wikimedia Commons file page). */
  source: string;
  /** Rights: "Public domain", "No known restrictions", "CC0 1.0", "CC BY 4.0" ... */
  license: string;
  /** Has a 400×240 full-screen version (images/archive/<id>-400.png). All items have 160, 96 and 48. */
  full?: boolean;
}

export const ARCHIVE: ArchiveItem[] = ARCHIVE_DATA;
export const ARCHIVE_SIZES = [400, 160, 96, 48] as const;
export type ArchiveSize = (typeof ARCHIVE_SIZES)[number];

const BY_ID: Map<string, ArchiveItem> = new Map(ARCHIVE.map(a => [a.id, a]));
export const archiveItem = (id: string | undefined): ArchiveItem | undefined => (id ? BY_ID.get(id) : undefined);

/** Client image path (no extension, Playdate style): "images/archive/raccoon-03-160". */
export const archivePath = (id: string, w: ArchiveSize = 160) => `images/archive/${id}-${w}`;

/** FNV-1a 32-bit. */
function hash(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

/**
 * Best picture for a list of tags (most specific first). Score = sum of matched tag weights,
 * where the first tag weighs most (2, 1.5, 1.33, 1.25 ...). Among the top-scoring items one is
 * chosen by hashing `seed`, so the same seed always gets the same picture. `exclude` skips ids
 * (e.g. pictures already used on the same page); `opts.full` keeps to items with a 400×240
 * version. Undefined when nothing matches any tag.
 */
export function pickArchive(tags: string[], seed: string, exclude?: string[], opts?: { full?: boolean }): string | undefined {
  if (!tags.length) return undefined;
  const want = new Map<string, number>();
  tags.forEach((t, i) => { if (!want.has(t)) want.set(t, 1 + 1 / (i + 1)); });
  const ex = exclude?.length ? new Set(exclude) : undefined;
  let best = 0;
  let pool: string[] = [];
  for (const it of ARCHIVE) {
    if (ex?.has(it.id) || (opts?.full && !it.full)) continue;
    let s = 0;
    for (const t of it.tags) s += want.get(t) ?? 0;
    if (s <= 0) continue;
    s = Math.round(s * 1000);
    if (s > best) { best = s; pool = [it.id]; }
    else if (s === best) pool.push(it.id);
  }
  if (!pool.length) return undefined;
  return pool[hash(`${seed}|${tags.join(",")}`) % pool.length];
}

/** pickArchive + caption, ready to spread into a Story / EventCard / MailItem. */
export function illustrate(tags: string[], seed: string, exclude?: string[], opts?: { full?: boolean }): { photo?: string; photoCaption?: string } {
  const id = pickArchive(tags, seed, exclude, opts);
  const it = archiveItem(id);
  return it ? { photo: it.id, photoCaption: it.caption } : {};
}

