/** Tags for a LifeEvent-like record (kind + data.sub / data.kind). */
export function lifeTags(kind: string, sub?: string): string[] {
  if (kind === "world") {
    const s = (sub ?? "").toLowerCase();
    const key = Object.keys(LIFE_TAGS).find(k => k.startsWith("world:") && s && (s === k.slice(6) || s.includes(k.slice(6))));
    return LIFE_TAGS[key ?? ""] ?? (/(storm|rain)/.test(s) ? LIFE_TAGS["world:weather"] : LIFE_TAGS.world);
  }
  if (kind === "drama" && sub && LIFE_TAGS[`drama:${sub}`]) return LIFE_TAGS[`drama:${sub}`];
  return LIFE_TAGS[kind] ?? [];
}
